#!/usr/bin/env python3
"""PREREG 31 checks: (1) positive control - text generated BY a 3-dial device (N=36, Zipf usage) must be recovered by the learner;
(2) are left/right crust and left/right mantle dependent in real words (MI vs shuffled pairs)?"""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
src = open(os.path.join(HERE, "s46_stolfi_dials.py")).read().split('p = os.path.join(OUT, "results_stolfi_dials.json")')[0]
exec(src)
rng = np.random.default_rng(SEED + 161)
tc = Counter(w for l in L(FIT) + L(DEV) for w in l)
pc, pm, co = Counter(), Counter(), Counter()
for w, c in tc.items():
    p = canonical(w, False)
    if p: pc[(p[0], p[4])] += c; pm[(p[1], p[3])] += c; co[p[2]] += c
def mi(C_):
    tot = sum(C_.values()); a, b = Counter(), Counter()
    for (x, y), c in C_.items(): a[x] += c; b[y] += c
    return sum(c / tot * np.log2(c * tot / (a[x] * b[y])) for (x, y), c in C_.items())
def mi_null(C_, reps=50):
    xs = [x for (x, y), c in C_.items() for _ in range(c)]; ys = [y for (x, y), c in C_.items() for _ in range(c)]; out = []
    for _ in range(reps):
        ys2 = list(rng.permutation(ys)); out.append(mi(Counter(zip(xs, ys2))))
    return np.mean(out), np.std(out, ddof=1)
for nm, C_ in (("crust L/R", pc), ("mantle L/R", pm)):
    m0 = mi(C_); mu, sd = mi_null(C_); print(nm, "MI %.3f bits, shuffled %.3f (sd %.4f), z %.0f" % (m0, mu, sd, (m0 - mu) / sd))
# positive control: generate 30000 train + 10000 test tokens from a dial device with 36 cells per dial (contents = real top-36)
dev = learn(tc, 36, False, "DIAL"); cr, ma, cor = [list(dev[k]) for k in ("crust", "mantle", "core")]
def zipf(n): w = 1 / np.arange(1, n + 1); return w / w.sum()
def gen(n):
    out = []
    for _ in range(n):
        a = cr[rng.choice(len(cr), p=zipf(len(cr)))]; b = ma[rng.choice(len(ma), p=zipf(len(ma)))]; c = cor[rng.choice(len(cor), p=zipf(len(cor)))]
        w = a[0] + b[0] + c + b[1] + a[1]
        if w: out.append(w)
    return out
tr, te = gen(30000), gen(10000)
res = evaluate(tr, te, "POSCTRL", np.random.default_rng(SEED + 162))
r = [x for x in res if x["variant"] == "STRICT" and x["mode"] == "DIAL" and x["N"] == 36][0]
print("POSITIVE CONTROL DIAL N36: test %.3f novel %.3f decoy %.3f n_novel %d" % (r["test_token_cov"], r["novel_type_cov"], r["decoy_cov"], r["n_novel"]))
